class Solution {
  public int numberOfCombinations(String num) {
    int n = num.length();
    int[][] lcp = new int[n + 1][n + 1];
    for (int i = n - 1; i >= 0; i--)
      for (int j = n - 1; j >= 0; j--)
        if (num.charAt(i) == num.charAt(j)) lcp[i][j] = lcp[i + 1][j + 1] + 1;
    int[][] dp = new int[n + 1][n + 1], prefix = new int[n + 1][n + 1];
    for (int end = 1; end <= n; end++) {
      if (num.charAt(0) != '0') dp[end][end] = 1;
      if (end == 1 && num.charAt(0) != '0') dp[end][1] = 1;
      else if (num.charAt(end - 1) != '0') dp[end][1] = prefix[end - 1][1];
      prefix[end][1] = dp[end][1];
      for (int len = 2; len <= end; len++) {
        int start = end - len;
        if (num.charAt(start) != '0') {
          long ways = prefix[start][Math.min(len - 1, start)];
          if (len <= start) {
            int common = lcp[start - len][start];
            if (common >= len || num.charAt(start - len + common) <= num.charAt(start + common))
              ways += dp[start][len];
          }
          dp[end][len] = (int) (ways % 1_000_000_007L);
        }
        prefix[end][len] = (int) ((prefix[end][len - 1] + (long) dp[end][len]) % 1_000_000_007L);
      }
    }
    return prefix[n][n];
  }
}
